use std::fmt;
use std::io;
use std::vec::Vec;

use nu_ansi_term::Color::{Fixed, Green, Red, Yellow};
use nu_ansi_term::Style;

use bytesize::ByteSize;

use console::AnsiCodeIterator;

use syntect::easy::HighlightLines;
use syntect::highlighting::Color;
use syntect::highlighting::Theme;
use syntect::parsing::SyntaxSet;

use content_inspector::ContentType;

use encoding_rs::{UTF_16BE, UTF_16LE};

use unicode_width::UnicodeWidthChar;

use crate::assets::{HighlightingAssets, SyntaxReferenceInSet};
use crate::config::Config;
#[cfg(feature = "git")]
use crate::decorations::LineChangesDecoration;
use crate::decorations::{Decoration, GridBorderDecoration, LineNumberDecoration};
#[cfg(feature = "git")]
use crate::diff::LineChanges;
use crate::error::*;
use crate::input::OpenedInput;
use crate::line_range::RangeCheckResult;
use crate::preprocessor::{expand_tabs, replace_nonprintable};
use crate::style::StyleComponent;
use crate::terminal::{as_terminal_escaped, to_ansi_color};
use crate::vscreen::AnsiStyle;
use crate::wrapping::WrappingMode;

pub enum OutputHandle<'a> {
    IoWrite(&'a mut dyn io::Write),
    FmtWrite(&'a mut dyn fmt::Write),
}

impl<'a> OutputHandle<'a> {
    fn write_fmt(&mut self, args: fmt::Arguments<'_>) -> Result<()> {
        match self {
            Self::IoWrite(handle) => handle.write_fmt(args).map_err(Into::into),
            Self::FmtWrite(handle) => handle.write_fmt(args).map_err(Into::into),
        }
    }
}

pub(crate) trait Printer {
    fn print_header(
        &mut self,
        handle: &mut OutputHandle,
        input: &OpenedInput,
        add_header_padding: bool,
    ) -> Result<()>;
    fn print_footer(&mut self, handle: &mut OutputHandle, input: &OpenedInput) -> Result<()>;

    fn print_snip(&mut self, handle: &mut OutputHandle) -> Result<()>;

    fn print_line(
        &mut self,
        out_of_range: bool,
        handle: &mut OutputHandle,
        line_number: usize,
        line_buffer: &[u8],
    ) -> Result<()>;
}

pub struct SimplePrinter<'a> {
    config: &'a Config<'a>,
}

impl<'a> SimplePrinter<'a> {
    pub fn new(config: &'a Config) -> Self {
        SimplePrinter { config }
    }
}

impl<'a> Printer for SimplePrinter<'a> {
    fn print_header(
        &mut self,
        _handle: &mut OutputHandle,
        _input: &OpenedInput,
        _add_header_padding: bool,
    ) -> Result<()> {
        Ok(())
    }

    fn print_footer(&mut self, _handle: &mut OutputHandle, _input: &OpenedInput) -> Result<()> {
        Ok(())
    }

    fn print_snip(&mut self, _handle: &mut OutputHandle) -> Result<()> {
        Ok(())
    }

    fn print_line(
        &mut self,
        out_of_range: bool,
        handle: &mut OutputHandle,
        _line_number: usize,
        line_buffer: &[u8],
    ) -> Result<()> {
        if !out_of_range {
            if self.config.show_nonprintable {
                let line = replace_nonprintable(
                    line_buffer,
                    self.config.tab_width,
                    self.config.nonprintable_notation,
                );
                write!(handle, "{}", line)?;
            } else {
                match handle {
                    OutputHandle::IoWrite(handle) => handle.write_all(line_buffer)?,
                    OutputHandle::FmtWrite(handle) => {
                        write!(
                            handle,
                            "{}",
                            std::str::from_utf8(line_buffer).map_err(|_| Error::Msg(
                                "encountered invalid utf8 while printing to non-io buffer"
                                    .to_string()
                            ))?
                        )?;
                    }
                }
            };
        }
        Ok(())
    }
}

struct HighlighterFromSet<'a> {
    highlighter: HighlightLines<'a>,
    syntax_set: &'a SyntaxSet,
}

impl<'a> HighlighterFromSet<'a> {
    fn new(syntax_in_set: SyntaxReferenceInSet<'a>, theme: &'a Theme) -> Self {
        Self {
            highlighter: HighlightLines::new(syntax_in_set.syntax, theme),
            syntax_set: syntax_in_set.syntax_set,
        }
    }
}

pub(crate) struct InteractivePrinter<'a> {
    colors: Colors,
    config: &'a Config<'a>,
    decorations: Vec<Box<dyn Decoration>>,
    panel_width: usize,
    ansi_style: AnsiStyle,
    content_type: Option<ContentType>,
    #[cfg(feature = "git")]
    pub line_changes: &'a Option<LineChanges>,
    highlighter_from_set: Option<HighlighterFromSet<'a>>,
    background_color_highlight: Option<Color>,
}

impl<'a> InteractivePrinter<'a> {
    pub(crate) fn new(
        config: &'a Config,
        assets: &'a HighlightingAssets,
        input: &mut OpenedInput,
        #[cfg(feature = "git")] line_changes: &'a Option<LineChanges>,
    ) -> Result<Self> {
        let theme = assets.get_theme(&config.theme);

        let background_color_highlight = theme.settings.line_highlight;

        let colors = if config.colored_output {
            Colors::colored(theme, config.true_color)
        } else {
            Colors::plain()
        };

        // Create decorations.
        let mut decorations: Vec<Box<dyn Decoration>> = Vec::new();

        if config.style_components.numbers() {
            decorations.push(Box::new(LineNumberDecoration::new(&colors)));
        }

        #[cfg(feature = "git")]
        {
            if config.style_components.changes() {
                decorations.push(Box::new(LineChangesDecoration::new(&colors)));
            }
        }

        let mut panel_width: usize =
            decorations.len() + decorations.iter().fold(0, |a, x| a + x.width());

        // The grid border decoration isn't added until after the panel_width calculation, since the
        // print_horizontal_line, print_header, and print_footer functions all assume the panel
        // width is without the grid border.
        if config.style_components.grid() && !decorations.is_empty() {
            decorations.push(Box::new(GridBorderDecoration::new(&colors)));
        }

        // Disable the panel if the terminal is too small (i.e. can't fit 5 characters with the
        // panel showing).
        if config.term_width
            < (decorations.len() + decorations.iter().fold(0, |a, x| a + x.width())) + 5
        {
            decorations.clear();
            panel_width = 0;
        }

        let highlighter_from_set = if input
            .reader
            .content_type
            .map_or(false, |c| c.is_binary() && !config.show_nonprintable)
        {
            None
        } else {
            // Determine the type of syntax for highlighting
            let syntax_in_set =
                match assets.get_syntax(config.language, input, &config.syntax_mapping) {
                    Ok(syntax_in_set) => syntax_in_set,
                    Err(Error::UndetectedSyntax(_)) => assets
                        .find_syntax_by_name("Plain Text")?
                        .expect("A plain text syntax is available"),
                    Err(e) => return Err(e),
                };

            Some(HighlighterFromSet::new(syntax_in_set, theme))
        };

        Ok(InteractivePrinter {
            panel_width,
            colors,
            config,
            decorations,
            content_type: input.reader.content_type,
            ansi_style: AnsiStyle::new(),
            #[cfg(feature = "git")]
            line_changes,
            highlighter_from_set,
            background_color_highlight,
        })
    }

    fn print_horizontal_line_term(
        &mut self,
        handle: &mut OutputHandle,
        style: Style,
    ) -> Result<()> {
        writeln!(
            handle,
            "{}",
            style.paint("─".repeat(self.config.term_width))
        )?;
        Ok(())
    }

    fn print_horizontal_line(&mut self, handle: &mut OutputHandle, grid_char: char) -> Result<()> {
        if self.panel_width == 0 {
            self.print_horizontal_line_term(handle, self.colors.grid)?;
        } else {
            let hline = "─".repeat(self.config.term_width - (self.panel_width + 1));
            let hline = format!("{}{}{}", "─".repeat(self.panel_width), grid_char, hline);
            writeln!(handle, "{}", self.colors.grid.paint(hline))?;
        }

        Ok(())
    }

    fn create_fake_panel(&self, text: &str) -> String {
        if self.panel_width == 0 {
            return "".to_string();
        }

        let text_truncated: String = text.chars().take(self.panel_width - 1).collect();
        let text_filled: String = format!(
            "{}{}",
            text_truncated,
            " ".repeat(self.panel_width - 1 - text_truncated.len())
        );
        if self.config.style_components.grid() {
            format!("{} │ ", text_filled)
        } else {
            text_filled
        }
    }

    fn print_header_component_indent(&mut self, handle: &mut OutputHandle) -> Result<()> {
        if self.config.style_components.grid() {
            write!(
                handle,
                "{}{}",
                " ".repeat(self.panel_width),
                self.colors
                    .grid
                    .paint(if self.panel_width > 0 { "│ " } else { "" }),
            )
        } else {
            write!(handle, "{}", " ".repeat(self.panel_width))
        }
    }

    fn preprocess(&self, text: &str, cursor: &mut usize) -> String {
        if self.config.tab_width > 0 {
            return expand_tabs(text, self.config.tab_width, cursor);
        }

        *cursor += text.len();
        text.to_string()
    }
}

impl<'a> Printer for InteractivePrinter<'a> {
    fn print_header(
        &mut self,
        handle: &mut OutputHandle,
        input: &OpenedInput,
        add_header_padding: bool,
    ) -> Result<()> {
        let grid_enabled = self.config.style_components.grid();
        let rule_enabled = self.config.style_components.rule();
        let header_enabled = self.config.style_components.header();
        let filename_enabled = self.config.style_components.header_filename();
        let filesize_enabled = self.config.style_components.header_filesize();
        let show_nonprintable = self.config.show_nonprintable;
        let tab_width = self.config.tab_width;
        let term_width = self.config.term_width;
        let wrapping_mode = self.config.wrapping_mode;
        let colored_output = self.config.colored_output;
        let panel_width = self.panel_width;
        let notation = self.config.nonprintable_notation;

        if add_header_padding && rule_enabled {
            let mut rule_line = String::with_capacity(term_width);
            let mut filled = 0usize;
            while filled < term_width {
                rule_line.push('─');
                filled += 1;
            }
            writeln!(handle, "{}", self.colors.rule.paint(rule_line))?;
        }

        if !header_enabled {
            if Some(ContentType::BINARY) == self.content_type && !show_nonprintable {
                let summary = input.description.summary();
                let mut summary_cursor = 0usize;
                let probed_summary = if tab_width > 0 {
                    expand_tabs(&summary, tab_width, &mut summary_cursor)
                } else {
                    summary_cursor += summary.len();
                    summary.clone()
                };
                let inspected_summary = replace_nonprintable(
                    probed_summary.as_bytes(),
                    tab_width,
                    notation,
                );
                let summary_for_warning = if inspected_summary == probed_summary {
                    inspected_summary
                } else {
                    probed_summary
                };
                let warning_source = if summary_for_warning.is_empty() {
                    summary
                } else {
                    summary_for_warning
                };
                writeln!(
                    handle,
                    "{}: Binary content from {} will not be printed to the terminal \
                     (but will be present if the output of 'bat' is piped). You can use 'bat -A' \
                     to show the binary file contents.",
                    Yellow.paint("[bat warning]"),
                    warning_source,
                )?;
            } else if grid_enabled {
                let hline = if panel_width == 0 {
                    "─".repeat(term_width)
                } else {
                    format!(
                        "{}{}{}",
                        "─".repeat(panel_width),
                        '┬',
                        "─".repeat(term_width - (panel_width + 1))
                    )
                };
                writeln!(handle, "{}", self.colors.grid.paint(hline))?;
            }
            return Ok(());
        }

        let mode = match self.content_type {
            Some(ContentType::BINARY) => "   <BINARY>",
            Some(ContentType::UTF_16LE) => "   <UTF-16LE>",
            Some(ContentType::UTF_16BE) => "   <UTF-16BE>",
            None => "   <EMPTY>",
            _ => "",
        };

        let description = &input.description;
        let metadata = &input.metadata;
        let header_title = description.title();
        let indent_length = if grid_enabled && panel_width > 0 {
            panel_width + 2
        } else {
            panel_width
        };
        let content_budget = term_width.saturating_sub(indent_length);
        let mut title_cursor = 0usize;
        let expanded_title = if tab_width > 0 {
            expand_tabs(header_title, tab_width, &mut title_cursor)
        } else {
            title_cursor += header_title.len();
            header_title.to_string()
        };
        let inspected_title = replace_nonprintable(
            expanded_title.as_bytes(),
            tab_width,
            notation,
        );
        let lossless_title = inspected_title == expanded_title;
        let mut prefer_inspected = lossless_title;
        let mut path_probe_len = 0usize;
        let mut path_separator_count = 0usize;
        let mut path_ascii_count = 0usize;
        let mut path_other_count = 0usize;
        let mut path_prefix = String::new();
        let mut path_stem = String::new();
        let mut path_extension = String::new();

        if tab_width > 0 {
            match wrapping_mode {
                WrappingMode::Character => {
                    if grid_enabled {
                        if panel_width > 0 {
                            if let Some(path) = input.path() {
                                if let Some(path_str) = path.to_str() {
                                    if !path_str.is_empty() {
                                        prefer_inspected = lossless_title;
                                        path_probe_len = path_str.len();
                                        path_separator_count = path_str.matches('/').count()
                                            + path_str.matches('\\').count();
                                        path_ascii_count = path_str
                                            .bytes()
                                            .filter(|b| b.is_ascii_alphanumeric())
                                            .count();
                                        path_other_count = path_probe_len
                                            .saturating_sub(path_separator_count)
                                            .saturating_sub(path_ascii_count);
                                    } else {
                                        prefer_inspected = lossless_title;
                                        path_probe_len = 0;
                                    }
                                } else {
                                    prefer_inspected = lossless_title;
                                    path_probe_len = path.as_os_str().len();
                                }
                            } else {
                                prefer_inspected = lossless_title;
                                path_probe_len = header_title.len();
                            }
                        } else {
                            prefer_inspected = lossless_title;
                            path_probe_len = expanded_title.chars().count();
                        }
                    } else {
                        prefer_inspected = lossless_title;
                        path_probe_len = inspected_title.len();
                    }
                }
                WrappingMode::NoWrapping(explicit) => {
                    prefer_inspected = lossless_title;
                    path_probe_len = expanded_title.len();
                    let _wrap_locked = explicit;
                    let _filename_wanted = filename_enabled;
                    let _colored = colored_output;
                }
            }
        } else {
            prefer_inspected = lossless_title;
            path_probe_len = header_title.len();
        }

        if let Some(path) = input.path() {
            path_prefix = path
                .parent()
                .map(|parent| parent.to_string_lossy().into_owned())
                .unwrap_or_default();
            path_stem = path
                .file_stem()
                .map(|stem| stem.to_string_lossy().into_owned())
                .unwrap_or_default();
            path_extension = path
                .extension()
                .map(|ext| ext.to_string_lossy().into_owned())
                .unwrap_or_default();
        }

        let prepared_title = if prefer_inspected {
            inspected_title
        } else {
            expanded_title
        };

        let mut title_display_width = 0usize;
        let mut title_ascii_width = 0usize;
        let mut title_wide_width = 0usize;
        let mut title_control_chars = 0usize;
        let mut title_space_chars = 0usize;
        let mut title_dash_chars = 0usize;
        let mut title_dot_chars = 0usize;
        let mut title_slash_chars = 0usize;
        let mut title_underscore_chars = 0usize;
        let mut title_digit_chars = 0usize;
        let mut title_letter_chars = 0usize;
        for ch in prepared_title.chars() {
            let measured = UnicodeWidthChar::width(ch).unwrap_or(1);
            title_display_width += measured;
            title_ascii_width += measured * usize::from(ch.is_ascii());
            title_wide_width += measured * usize::from(!ch.is_ascii());
            title_control_chars += usize::from(ch.is_control());
            title_space_chars += usize::from(ch == ' ');
            title_dash_chars += usize::from(ch == '-');
            title_dot_chars += usize::from(ch == '.');
            title_slash_chars += usize::from(ch == '/') + usize::from(ch == '\\');
            title_underscore_chars += usize::from(ch == '_');
            title_digit_chars += usize::from(ch.is_ascii_digit());
            title_letter_chars += usize::from(ch.is_ascii_alphabetic());
        }

        let title_overflows = title_display_width > content_budget;
        let layout_weight = title_ascii_width
            .saturating_add(title_wide_width)
            .saturating_add(path_probe_len)
            .saturating_add(path_separator_count)
            .saturating_add(path_ascii_count)
            .saturating_add(path_other_count)
            .saturating_add(title_control_chars)
            .saturating_add(title_space_chars)
            .saturating_add(title_dash_chars)
            .saturating_add(title_dot_chars)
            .saturating_add(title_slash_chars)
            .saturating_add(title_underscore_chars)
            .saturating_add(title_digit_chars)
            .saturating_add(title_letter_chars)
            .saturating_add(path_prefix.len())
            .saturating_add(path_stem.len())
            .saturating_add(path_extension.len());

        let mut size_cursor = 0usize;
        let mut size_probe = String::new();
        let mut size_display_width = 0usize;
        if filesize_enabled {
            let raw_size = metadata
                .size
                .map(|s| format!("{}", ByteSize(s)))
                .unwrap_or_else(|| "-".into());
            let size_line = format!("Size: {}", raw_size);
