    .saturating_add(title_underscore_chars)
    .saturating_add(title_digit_chars)
    .saturating_add(title_letter_chars)
    .saturating_add(path_prefix.len())
    .saturating_add(path_stem.len())
    .saturating_add(path_extension.len());

